const fs=require('fs');
function init(){
 const s={items:{},W:[6,4],C:[2,2],D:[6,2],G:[2,5],dead:false,gateOpen:false,sel:1};
 const cr=[[5,4],[6,3],[4,2],[2,3],[2,4],[4,3],[5,6],[2,6],[3,2],[3,6],[3,5],[4,5],[4,6],[5,5],[5,2],[5,3],[4,4],[3,3],[3,4]];
 s.cr=new Set(cr.map(c=>c+''));
 return s;}
const dirs={U:[0,-1],D:[0,1],L:[-1,0],R:[1,0]};
function key(p){return p[0]+','+p[1]}
function what(s,x,y){ // returns type at cell or null
 const k=x+','+y;
 if(s.W&&key(s.W)==k)return 'W'; if(s.C&&key(s.C)==k)return 'C';
 if(s.D&&key(s.D)==k)return 'D'; if(s.G&&key(s.G)==k)return 'g';
 if(s.cr.has(k))return '*'; return null;}
function floor(s,x,y){ if(x<2||x>6||y<2||y>6)return false; if(x==6&&(y==5||y==6))return s.gateOpen; return true;}
function setpos(s,t,p){ if(t=='*')return; s[t=='g'?'G':t]=p;}
function settle(s){
 // attacks
 const kills=[];
 const prot=(p)=>s.C&&(Math.abs(p[0]-s.C[0])+Math.abs(p[1]-s.C[1])==1);
 const nb=[[1,0],[-1,0],[0,1],[0,-1]];
 if(s.G){ for(const d of nb){const t=what(s,s.G[0]+d[0],s.G[1]+d[1]); 
   if(t=='W'&&!prot(s.W))kills.push('W'); if(t=='C'){} if(t=='D')kills.push('D');}}
 if(s.D){ let x=s.D[0]-1,y=s.D[1]; while(floor(s,x,y)){const t=what(s,x,y); if(t){ if(t=='W'&&!prot(s.W))kills.push('W'); if(t=='g')kills.push('g'); break;} x--; } }
 for(const k of kills){ if(k=='W'){s.dead=true;s.W=null;} if(k=='D')s.D=null; if(k=='g')s.G=null;}
 if(!s.D&&!s.G)s.gateOpen=true;
}
function move(s,m){
 if(s.dead)return;
 if(m=='C'){s.sel=3-s.sel;return;}
 const d=dirs[m];
 if(s.sel==1){
  let x=s.W[0]+d[0],y=s.W[1]+d[1]; let first=null;
  while(floor(s,x,y)){const t=what(s,x,y); if(t){first=[x,y,t];break;} x+=d[0];y+=d[1];}
  if(first){ const old=s.W; const [fx,fy,t]=first;
    if(t=='*'){s.cr.delete(fx+','+fy);s.cr.add(key(old));}
    else {setpos(s,t,old);} s.W=[fx,fy];}
  else { const nx=s.W[0]+d[0],ny=s.W[1]+d[1]; if(floor(s,nx,ny)&&!what(s,nx,ny))s.W=[nx,ny]; else {s.err='refused '+m;return;}}
 } else {
  const nx=s.C[0]+d[0],ny=s.C[1]+d[1]; if(floor(s,nx,ny)&&!what(s,nx,ny))s.C=[nx,ny]; else {s.err='refused C'+m;return;}
 }
 settle(s);
}
function run(str,verbose){
 const s=init(); let i=0;
 for(const m of str.replace(/\s/g,'')){ s.err=null; move(s,m); i++; if(s.err||s.dead){console.log('problem at',i,m,s.err,s.dead);break;} }
 return s;}
function show(s){
 let out='';
 for(let y=2;y<=6;y++){let r='';for(let x=2;x<=6;x++){const t=what(s,x,y); r+= t?t:((x==6&&y>=5)?(s.gateOpen?"'":'%'):'.');} out+=r+'\n';}
 console.log(out+(s.dead?'DEAD':''));
}
